begin;
create type public.band_role as enum ('owner','admin','editor','member');
create type public.job_state as enum ('queued','processing','completed','failed','canceled','expired');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text not null default '' check(length(display_name)<=80),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.bands(id uuid primary key default gen_random_uuid(),name text not null check(length(name) between 1 and 100),suspended boolean not null default false,created_at timestamptz not null default now());
create table public.band_memberships(band_id uuid references public.bands(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,role public.band_role not null default 'member',created_at timestamptz not null default now(),primary key(band_id,user_id));
create index membership_user on public.band_memberships(user_id);
create table public.entitlements(band_id uuid primary key references public.bands(id) on delete cascade,storage_limit bigint not null default 2147483648 check(storage_limit>=0),file_limit bigint not null default 262144000 check(file_limit>0),ai_seconds_limit integer not null default 600 check(ai_seconds_limit>0),ai_monthly_seconds integer not null default 3600 check(ai_monthly_seconds>=0),member_limit integer not null default 20 check(member_limit>0),active_jobs_limit integer not null default 1 check(active_jobs_limit between 1 and 10),plan text not null default 'beta');
create table public.band_usage(band_id uuid primary key references public.bands(id) on delete cascade,stored_bytes bigint not null default 0 check(stored_bytes>=0),reserved_bytes bigint not null default 0 check(reserved_bytes>=0),downloaded_bytes bigint not null default 0,updated_at timestamptz not null default now());
create table public.invitations(id uuid primary key default gen_random_uuid(),band_id uuid not null references public.bands(id) on delete cascade,email text not null,role public.band_role not null check(role<>'owner'),token_hash text unique not null,created_by uuid references auth.users(id) on delete set null,expires_at timestamptz not null default now()+interval '48 hours',accepted_at timestamptz,declined_at timestamptz,created_at timestamptz not null default now());
create index invitation_band on public.invitations(band_id);
create table public.songs(id uuid primary key default gen_random_uuid(),band_id uuid not null references public.bands(id) on delete cascade,data jsonb not null,approved boolean not null default true,revision bigint not null default 1,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,band_id));
create index songs_band on public.songs(band_id);
create table public.charts(id uuid primary key default gen_random_uuid(),song_id uuid not null,band_id uuid not null,section_id text not null,kind text not null check(kind in ('lyrics','chords','tabs')),instrument text not null default '',content text not null,foreign key(song_id,band_id) references public.songs(id,band_id) on delete cascade,unique(song_id,section_id,kind,instrument));
create table public.arrangements(song_id uuid primary key,band_id uuid not null,mix jsonb not null default '[]',updated_at timestamptz not null default now(),foreign key(song_id,band_id) references public.songs(id,band_id) on delete cascade);
create table public.setlists(id uuid primary key default gen_random_uuid(),band_id uuid not null references public.bands(id) on delete cascade,name text not null default 'Rehearsal set',is_default boolean not null default true,unique(band_id,is_default));
create table public.setlist_items(setlist_id uuid references public.setlists(id) on delete cascade,song_id uuid references public.songs(id) on delete cascade,position integer not null check(position>=0),primary key(setlist_id,song_id),unique(setlist_id,position));
create table public.audio_assets(id uuid primary key default gen_random_uuid(),band_id uuid not null,song_id uuid not null,bucket text not null check(bucket in ('originals','stems','charts','temporary')),object_key text not null unique,filename text not null,category text not null default 'other' check(category in ('vocals','drums','bass','guitar','keyboards','backing vocals','other','click','spoken cues')),bytes bigint not null check(bytes>=0),duration double precision not null default 0 check(duration>=0),sample_rate integer not null default 44100,source text not null check(source in ('import','ai','original','chart')),status text not null default 'pending' check(status in ('pending','verified','deleting')),created_at timestamptz not null default now(),foreign key(song_id,band_id) references public.songs(id,band_id) on delete cascade);
create index assets_song on public.audio_assets(song_id);
create table public.storage_reservations(id uuid primary key,band_id uuid not null references public.bands(id) on delete cascade,song_id uuid not null references public.songs(id) on delete cascade,user_id uuid references auth.users(id) on delete set null,asset_id uuid unique not null references public.audio_assets(id) on delete cascade,bytes bigint not null check(bytes>0),state text not null default 'active' check(state in ('active','committed','released','expired')),expires_at timestamptz not null default now()+interval '24 hours',created_at timestamptz not null default now());
create index reservations_band on public.storage_reservations(band_id,state);
create table public.playback_sessions(id uuid primary key default gen_random_uuid(),code text not null unique,band_id uuid not null references public.bands(id) on delete cascade,leader_id uuid not null references auth.users(id),data jsonb not null,revision bigint not null default 1,expires_at timestamptz not null default now()+interval '24 hours',created_at timestamptz not null default now());
create index sessions_band on public.playback_sessions(band_id);
create table public.session_devices(id uuid primary key default gen_random_uuid(),session_id uuid not null references public.playback_sessions(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,name text not null,role text not null check(role in ('musician','audience')),instrument text not null default 'Guitar',ready boolean not null default false,song_id uuid,last_seen timestamptz not null default now());
create table public.session_controllers(session_id uuid references public.playback_sessions(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,primary key(session_id,user_id));
create table public.processing_jobs(id uuid primary key,band_id uuid not null,song_id uuid not null,input_asset_id uuid not null references public.audio_assets(id),created_by uuid references auth.users(id) on delete set null,status public.job_state not null default 'queued',idempotency_key text not null,attempt integer not null default 0,max_attempts integer not null default 3,duration_seconds integer not null check(duration_seconds>0),output_reserved_bytes bigint not null check(output_reserved_bytes>=0),lease_hash text,lease_expires_at timestamptz,error text,results jsonb not null default '[]',saved boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(song_id,band_id) references public.songs(id,band_id) on delete cascade,unique(band_id,idempotency_key));
create unique index one_active_job_per_band on public.processing_jobs(band_id) where status in ('queued','processing');
create table public.processing_usage(id uuid primary key default gen_random_uuid(),job_id uuid unique references public.processing_jobs(id) on delete set null,band_id uuid references public.bands(id) on delete set null,month date not null,seconds integer not null check(seconds>=0),state text not null check(state in ('reserved','consumed','released')));
create index ai_usage_month on public.processing_usage(band_id,month);
create table public.platform_config(id boolean primary key default true check(id),ai_enabled boolean not null default false,monthly_ai_seconds_cap integer not null default 36000,worker_online_at timestamptz);
insert into public.platform_config(id) values(true);
create table public.audit_events(id bigint generated always as identity primary key,band_id uuid references public.bands(id) on delete set null,actor_id uuid references auth.users(id) on delete set null,action text not null,details jsonb not null default '{}',created_at timestamptz not null default now());
create table public.cleanup_jobs(id uuid primary key default gen_random_uuid(),band_id uuid,bucket text not null,object_key text not null,attempt integer not null default 0,status text not null default 'queued' check(status in ('queued','processing','completed','failed')),next_attempt_at timestamptz not null default now(),error text,created_at timestamptz not null default now(),unique(bucket,object_key));
create table public.operation_events(id bigint generated always as identity primary key,environment text not null,kind text not null,band_id uuid,details jsonb not null default '{}',created_at timestamptz not null default now());

create function public.band_permission(b uuid,roles public.band_role[] default array['owner','admin','editor','member']::public.band_role[]) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.band_memberships m join public.bands bnd on bnd.id=m.band_id where m.band_id=b and m.user_id=auth.uid() and m.role=any(roles) and not bnd.suspended) $$;
create function public.band_owner(b uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.band_memberships where band_id=b and user_id=auth.uid() and role='owner')$$;
create function public.session_access(s uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.playback_sessions p where p.id=s and p.expires_at>now() and public.band_permission(p.band_id))$$;
create function public.session_control(s uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.playback_sessions p where p.id=s and public.session_access(s) and (p.leader_id=auth.uid() or exists(select 1 from public.session_controllers c where c.session_id=s and c.user_id=auth.uid())))$$;

alter table public.profiles enable row level security;
create policy own_profile on public.profiles for all to authenticated using(id=auth.uid()) with check(id=auth.uid());
alter table public.bands enable row level security;
create policy band_read on public.bands for select to authenticated using(public.band_permission(id) or public.band_owner(id));
alter table public.band_memberships enable row level security;
create policy membership_read on public.band_memberships for select to authenticated using(user_id=auth.uid() or public.band_permission(band_id));
do $$declare t text;begin foreach t in array array['entitlements','band_usage','invitations','songs','charts','arrangements','setlists','audio_assets','storage_reservations','processing_jobs','processing_usage','audit_events'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy band_read on public.%I for select to authenticated using(public.band_permission(band_id))',t);end loop;end$$;
-- Writes go through checked transactional RPCs; ordinary clients cannot alter quotas or membership.
create policy songs_insert on public.songs for insert to authenticated with check(public.band_permission(band_id,array['owner','admin','editor']::public.band_role[]) and created_by=auth.uid());
create policy songs_update on public.songs for update to authenticated using(public.band_permission(band_id,array['owner','admin','editor']::public.band_role[])) with check(public.band_permission(band_id,array['owner','admin','editor']::public.band_role[]));
create policy songs_delete on public.songs for delete to authenticated using(public.band_permission(band_id,array['owner','admin','editor']::public.band_role[]));
create policy audit_insert on public.audit_events for insert to authenticated with check(actor_id=auth.uid() and public.band_permission(band_id));
alter table public.setlist_items enable row level security;
create policy set_items_read on public.setlist_items for select to authenticated using(exists(select 1 from public.setlists s where s.id=setlist_id and public.band_permission(s.band_id)));
alter table public.playback_sessions enable row level security;
create policy sessions_read on public.playback_sessions for select to authenticated using(public.session_access(id));
alter table public.session_devices enable row level security;
create policy devices_read on public.session_devices for select to authenticated using(public.session_access(session_id));
alter table public.session_controllers enable row level security;
create policy controllers_read on public.session_controllers for select to authenticated using(public.session_access(session_id));
alter table public.platform_config enable row level security;
alter table public.cleanup_jobs enable row level security;
alter table public.operation_events enable row level security;

create function public.initialize_profile() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,display_name) values(new.id,left(coalesce(new.raw_user_meta_data->>'display_name',''),80));return new;end$$;
create trigger new_user_profile after insert on auth.users for each row execute function public.initialize_profile();
create function public.create_band(band_name text) returns uuid language plpgsql security definer set search_path=public as $$declare b uuid;begin if auth.uid() is null then raise exception 'BR:Sign in';end if;perform public.take_request('band.create',5);perform pg_advisory_xact_lock(hashtext(auth.uid()::text));if (select count(*) from public.band_memberships where user_id=auth.uid() and role='owner')>=5 then raise exception 'BR:Five owned workspaces maximum. Contact the app administrator.';end if;insert into public.bands(name) values(trim(band_name)) returning id into b;insert into public.band_memberships values(b,auth.uid(),'owner',now());insert into public.entitlements(band_id) values(b);insert into public.band_usage(band_id) values(b);insert into public.setlists(band_id) values(b);insert into public.audit_events(band_id,actor_id,action) values(b,auth.uid(),'band.created');return b;end$$;
create function public.invite_member(b uuid,invite_email text,invite_role public.band_role,hash text) returns uuid language plpgsql security definer set search_path=public as $$declare i uuid;begin if not public.band_permission(b,array['owner','admin']::public.band_role[]) or invite_role='owner' or (invite_role='admin' and not public.band_owner(b)) then raise exception 'BR:Invitation permission denied';end if;perform public.take_request('band.invite',30);insert into public.invitations(band_id,email,role,token_hash,created_by) values(b,lower(trim(invite_email)),invite_role,hash,auth.uid()) returning id into i;insert into public.audit_events(band_id,actor_id,action,details) values(b,auth.uid(),'member.invited',jsonb_build_object('invitation',i));return i;end$$;
create function public.respond_invitation(hash text,accept boolean) returns uuid language plpgsql security definer set search_path=public as $$declare i public.invitations;e text;c integer;lim integer;begin select * into i from public.invitations where token_hash=hash for update;if not found or i.expires_at<=now() or i.accepted_at is not null or i.declined_at is not null then raise exception 'BR:Invitation expired or used';end if;select lower(email) into e from auth.users where id=auth.uid() and email_confirmed_at is not null;if e is null or e<>i.email then raise exception 'BR:Sign in with the verified invited email';end if;if accept then perform 1 from public.bands where id=i.band_id for update;select count(*) into c from public.band_memberships where band_id=i.band_id;select member_limit into lim from public.entitlements where band_id=i.band_id;if c>=lim then raise exception 'BR:Band member limit reached';end if;insert into public.band_memberships(band_id,user_id,role) values(i.band_id,auth.uid(),i.role) on conflict do nothing;update public.invitations set accepted_at=now() where id=i.id;else update public.invitations set declined_at=now() where id=i.id;end if;insert into public.audit_events(band_id,actor_id,action) values(i.band_id,auth.uid(),case when accept then 'invitation.accepted' else 'invitation.declined' end);return i.band_id;end$$;
create function public.manage_member(b uuid,target uuid,new_role public.band_role default null) returns void language plpgsql security definer set search_path=public as $$declare member_role public.band_role;owners integer;begin perform 1 from public.bands where id=b for update;select role into member_role from public.band_memberships where band_id=b and user_id=target;if not found then raise exception 'BR:Member missing';end if;if target<>auth.uid() and not public.band_permission(b,array['owner','admin']::public.band_role[]) then raise exception 'BR:Permission denied';end if;if not public.band_owner(b) and (member_role in ('owner','admin') or new_role in ('owner','admin') or new_role is not null and target=auth.uid()) then raise exception 'BR:Only owners manage administrators';end if;if member_role='owner' and (new_role is null or new_role<>'owner') then select count(*) into owners from public.band_memberships where band_id=b and role='owner';if owners<=1 then raise exception 'BR:Transfer ownership before leaving';end if;end if;if new_role is null then delete from public.band_memberships where band_id=b and user_id=target;delete from public.session_devices where user_id=target and session_id in(select id from public.playback_sessions where band_id=b);delete from public.session_controllers where user_id=target and session_id in(select id from public.playback_sessions where band_id=b);else update public.band_memberships set role=new_role where band_id=b and user_id=target;end if;insert into public.audit_events(band_id,actor_id,action,details) values(b,auth.uid(),'membership.changed',jsonb_build_object('user',target,'role',new_role));end$$;
create function public.transfer_ownership(b uuid,target uuid) returns void language plpgsql security definer set search_path=public as $$begin if not public.band_owner(b) or target=auth.uid() then raise exception 'BR:Ownership transfer denied';end if;perform 1 from public.bands where id=b for update;if not exists(select 1 from public.band_memberships where band_id=b and user_id=target) then raise exception 'BR:Choose an existing band member';end if;update public.band_memberships set role='owner' where band_id=b and user_id=target;update public.band_memberships set role='admin' where band_id=b and user_id=auth.uid();update public.playback_sessions set leader_id=target where band_id=b and leader_id=auth.uid();insert into public.audit_events(band_id,actor_id,action,details) values(b,auth.uid(),'ownership.transferred',jsonb_build_object('user',target));end$$;

-- Atomically reserve capacity before storage receives bytes. UUID idempotency keys are reusable on retry.
create function public.reserve_upload(b uuid,s uuid,a uuid,reservation uuid,file_name text,file_bytes bigint,file_duration double precision,file_rate integer,asset_source text) returns public.audio_assets language plpgsql security definer set search_path=public as $$declare u public.band_usage;e public.entitlements;asset public.audio_assets;k text;bucket_name text;reserve_bytes bigint;begin if not public.band_permission(b,array['owner','admin','editor']::public.band_role[]) then raise exception 'BR:Editor permission required';end if;perform public.take_request('audio.upload',60);select * into u from public.band_usage where band_id=b for update;select * into e from public.entitlements where band_id=b;select * into asset from public.audio_assets where id=a;if found then if asset.band_id<>b or asset.song_id<>s then raise exception 'BR:Conflicting upload';end if;return asset;end if;if not exists(select 1 from public.songs where id=s and band_id=b) then raise exception 'BR:Song missing';end if;if asset_source='import' and (select count(*) from public.audio_assets where song_id=s and source='import' and status<>'deleting')>=24 then raise exception 'BR:Maximum 24 imported stems';end if;if file_bytes<=0 or file_bytes>e.file_limit or file_duration<=0 or file_duration>7200 or file_rate not between 8000 and 192000 then raise exception 'BR:Invalid audio size or metadata';end if;bucket_name=case when asset_source='original' then 'originals' else 'temporary' end;select file_size_limit into reserve_bytes from storage.buckets where id=bucket_name;reserve_bytes=greatest(file_bytes,coalesce(reserve_bytes,e.file_limit));if u.stored_bytes+u.reserved_bytes+reserve_bytes>e.storage_limit then raise exception 'BR:Storage allowance exceeded';end if;bucket_name=case when asset_source='original' then 'originals' else 'temporary' end;k='bands/'||b||'/songs/'||s||'/'||a||'/'||regexp_replace(left(file_name,100),'[^a-zA-Z0-9_.-]','_','g');insert into public.audio_assets(id,band_id,song_id,bucket,object_key,filename,bytes,duration,sample_rate,source) values(a,b,s,bucket_name,k,left(file_name,100),file_bytes,file_duration,file_rate,asset_source) returning * into asset;insert into public.storage_reservations(id,band_id,song_id,user_id,asset_id,bytes) values(reservation,b,s,auth.uid(),a,reserve_bytes);update public.band_usage set reserved_bytes=reserved_bytes+reserve_bytes,updated_at=now() where band_id=b;return asset;end$$;

-- Only the trusted verifier can finalize. Storage object's actual size is checked, not client declarations.
create function public.finalize_upload(a uuid,actual_bytes bigint,actual_duration double precision,actual_rate integer,category text) returns public.audio_assets language plpgsql security definer set search_path=public as $$declare asset public.audio_assets;r public.storage_reservations;begin select * into asset from public.audio_assets where id=a for update;if not found then raise exception 'BR:Upload missing';end if;if asset.status='verified' then return asset;end if;select * into r from public.storage_reservations where asset_id=a for update;if r.state<>'active' or r.expires_at<=now() or actual_bytes<>asset.bytes or actual_duration<=0 then raise exception 'BR:Upload verification mismatch';end if;update public.audio_assets set status='verified',duration=actual_duration,sample_rate=actual_rate,category=finalize_upload.category where id=a returning * into asset;update public.storage_reservations set state='committed' where id=r.id;update public.band_usage set reserved_bytes=greatest(0,reserved_bytes-r.bytes),stored_bytes=stored_bytes+actual_bytes,updated_at=now() where band_id=asset.band_id;return asset;end$$;
create function public.release_upload(a uuid) returns void language plpgsql security definer set search_path=public as $$declare r public.storage_reservations;asset public.audio_assets;begin select * into asset from public.audio_assets where id=a for update;select * into r from public.storage_reservations where asset_id=a for update;if r.state='active' then update public.band_usage set reserved_bytes=greatest(0,reserved_bytes-r.bytes) where band_id=r.band_id;update public.storage_reservations set state='released' where id=r.id;end if;if asset.status='pending' then insert into public.cleanup_jobs(band_id,bucket,object_key) values(asset.band_id,asset.bucket,asset.object_key) on conflict do nothing;update public.audio_assets set status='deleting' where id=a;end if;end$$;

-- Every asset deletion schedules retryable cleanup before the database row disappears.
create function public.enqueue_asset_cleanup() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.cleanup_jobs(band_id,bucket,object_key) values(old.band_id,old.bucket,old.object_key) on conflict do nothing;update public.band_usage set stored_bytes=greatest(0,stored_bytes-case when old.status='verified' then old.bytes else 0 end) where band_id=old.band_id;update public.band_usage set reserved_bytes=greatest(0,reserved_bytes-coalesce((select bytes from public.storage_reservations where asset_id=old.id and state='active'),0)) where band_id=old.band_id;return old;end$$;
create trigger asset_cleanup before delete on public.audio_assets for each row execute function public.enqueue_asset_cleanup();
create function public.delete_asset(a uuid) returns void language plpgsql security definer set search_path=public as $$declare b uuid;begin select band_id into b from public.audio_assets where id=a;if not public.band_permission(b,array['owner','admin','editor']::public.band_role[]) then raise exception 'BR:Delete permission denied';end if;delete from public.audio_assets where id=a;end$$;
create function public.delete_band(b uuid) returns void language plpgsql security definer set search_path=public as $$begin if not public.band_owner(b) then raise exception 'BR:Only the owner can delete a band';end if;insert into public.audit_events(actor_id,action,details) values(auth.uid(),'band.deleted',jsonb_build_object('band',b));delete from public.bands where id=b;end$$;

create function public.replace_setlist(b uuid,ids uuid[]) returns void language plpgsql security definer set search_path=public as $$declare list uuid;i uuid;n integer=0;begin if not public.band_permission(b,array['owner','admin','editor']::public.band_role[]) then raise exception 'BR:Editor permission required';end if;select id into list from public.setlists where band_id=b and is_default for update;delete from public.setlist_items where setlist_id=list;foreach i in array ids loop if not exists(select 1 from public.songs where id=i and band_id=b) then raise exception 'BR:Song outside workspace';end if;insert into public.setlist_items values(list,i,n);n=n+1;end loop;end$$;

-- Keep charts and mix records synchronized with the existing song JSON format.
create function public.sync_song_parts() returns trigger language plpgsql security definer set search_path=public as $$declare part jsonb;tab record;begin delete from public.charts where song_id=new.id;for part in select value from jsonb_array_elements(coalesce(new.data->'sections','[]')) loop insert into public.charts(song_id,band_id,section_id,kind,content) values(new.id,new.band_id,part->>'id','lyrics',coalesce(part->>'lyrics','')),(new.id,new.band_id,part->>'id','chords',coalesce(part->>'chords',''));for tab in select * from jsonb_each_text(coalesce(part->'tabs','{}')) loop insert into public.charts(song_id,band_id,section_id,kind,instrument,content) values(new.id,new.band_id,part->>'id','tabs',tab.key,tab.value);end loop;end loop;insert into public.arrangements(song_id,band_id,mix) values(new.id,new.band_id,coalesce(new.data->'stems','[]')) on conflict(song_id) do update set mix=excluded.mix,updated_at=now();return new;end$$;
create trigger song_parts after insert or update of data on public.songs for each row execute function public.sync_song_parts();

-- Private storage: uploads are restricted to an existing live reservation and exact object key.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('originals','originals',false,262144000,array['audio/wav','audio/x-wav','audio/mpeg','audio/mp4','audio/aac','application/octet-stream']),('stems','stems',false,1073741824,array['audio/wav','audio/x-wav']),('temporary','temporary',false,262144000,array['audio/wav','audio/x-wav','audio/mpeg','audio/mp4','audio/aac','application/octet-stream']),('charts','charts',false,10485760,array['application/pdf','text/plain']) on conflict(id) do nothing;
create policy reserved_audio_insert on storage.objects for insert to authenticated with check(exists(select 1 from public.audio_assets a join public.storage_reservations r on r.asset_id=a.id where a.object_key=name and a.bucket=bucket_id and a.status='pending' and r.state='active' and r.expires_at>now() and public.band_permission(a.band_id,array['owner','admin','editor']::public.band_role[])));
-- Reads use checked 60-second signed URLs. No direct storage SELECT policy is granted to users.
-- This also prevents an audience device bypassing the audio-role gate through Supabase's storage endpoint.

create policy private_session_receive on realtime.messages for select to authenticated using(extension='broadcast' and exists(select 1 from public.playback_sessions s where 'session:'||s.id::text=(select realtime.topic()) and public.session_access(s.id)));
-- Clients cannot broadcast commands. Committed database updates are the authoritative source.
create function public.broadcast_session_change() returns trigger language plpgsql security definer set search_path=public as $$begin perform realtime.send(jsonb_build_object('revision',new.revision),'state','session:'||new.id::text,true);return new;end$$;
create trigger session_broadcast after update on public.playback_sessions for each row execute function public.broadcast_session_change();

-- Minimize SECURITY DEFINER exposure. Internal worker/finalization functions are service-role only.
revoke execute on all functions in schema public from public,anon,authenticated;
grant execute on function public.band_permission(uuid,public.band_role[]),public.band_owner(uuid),public.session_access(uuid),public.session_control(uuid),public.create_band(text),public.invite_member(uuid,text,public.band_role,text),public.respond_invitation(text,boolean),public.manage_member(uuid,uuid,public.band_role),public.transfer_ownership(uuid,uuid),public.reserve_upload(uuid,uuid,uuid,uuid,text,bigint,double precision,integer,text),public.delete_asset(uuid),public.delete_band(uuid),public.replace_setlist(uuid,uuid[]) to authenticated;
grant execute on all functions in schema public to service_role;
grant select,insert,update,delete on all tables in schema public to authenticated,service_role;
grant usage,select on all sequences in schema public to authenticated,service_role;
commit;
